class Event:
    def __init__(self, type_):
        self.type = type_
        self._stop = False
    def stopPropagation(self):
        self._stop = True

class Element:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent
        self.listeners = []
        self.children = []
        if parent is not None:
            parent.children.append(self)
    def addEventListener(self, phase, cb):
        self.listeners.append((phase, cb))
    def _path_to_root(self):
        p = []
        cur = self
        while cur is not None:
            p.append(cur)
            cur = cur.parent
        return p
    def dispatch(self, ev):
        path = self._path_to_root()
        for node in reversed(path):
            if node is self:
                continue
            if ev._stop:
                break
            for phase, cb in node.listeners:
                if phase == 'capture':
                    cb(ev, node)
        for phase, cb in self.listeners:
            if ev._stop:
                break
            cb(ev, self)
        for node in path[1:]:
            if ev._stop:
                break
            for phase, cb in node.listeners:
                if phase == 'bubble':
                    cb(ev, node)

def make(label):
    def handler(ev, node):
        print(label + ' @ ' + node.name)
    return handler

root = Element('root')
mid = Element('mid', root)
leaf = Element('leaf', mid)
root.addEventListener('capture', make('root捕获'))
mid.addEventListener('capture', make('mid捕获'))
leaf.addEventListener('capture', make('leaf捕获'))
root.addEventListener('bubble', make('root冒泡'))
mid.addEventListener('bubble', make('mid冒泡'))
leaf.addEventListener('bubble', make('leaf冒泡'))
ev = Event('click')
leaf.dispatch(ev)
